{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-07",
  "sketch": {
    "components": ["Mobile app", "TLS client / certificate validation", "Bundled config file", "Environment flag reader", "Backend API"],
    "dataStores": ["Bundled release config file"],
    "externalServices": ["Backend API over TLS"],
    "trustBoundaries": ["Mobile device to backend over the network", "App code to on-device config file"],
    "dataClasses": ["credentials"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "Spoofing",
      "title": "Any TLS certificate is accepted, so an attacker on the network can impersonate the server",
      "scenario": "An attacker on the same Wi-Fi, a hostile mobile network or a compromised DNS/proxy presents a self-signed certificate for the backend host. Because the app accepts any TLS certificate when the flag is set, the handshake succeeds and the attacker becomes a full man-in-the-middle: they read and rewrite every request and response, including login credentials and session tokens, with no warning shown to the user.",
      "component": "Mobile app TLS certificate validation",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "To help testing, the app accepts any TLS certificate when the environment flag is set." }
      ],
      "cwe": ["CWE-295", "CWE-297"],
      "plainLanguage": "The app does not check who it is really talking to, so someone on the same network can pretend to be the server and read or change everything.",
      "requirement": {
        "title": "Always validate the server certificate chain and hostname",
        "given": "the mobile app connects to the backend over TLS",
        "when": "the server presents a certificate that is self-signed, expired, or issued for a different hostname",
        "then": "the app aborts the connection and sends no request data, with no configuration flag able to disable this check"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Testing bypass for certificate checks is compiled into the production release build",
      "scenario": "The certificate-bypass code path and the flag that enables it are present in the shipped release binary rather than being limited to debug builds. Anyone who can set that flag, including an attacker on a jailbroken/rooted device, a malicious repackaged build, or a mistaken release-time configuration, turns off certificate validation for real users and real production traffic.",
      "component": "Release build configuration / environment flag",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "The flag is read from a config file bundled in the release build." }
      ],
      "cwe": ["CWE-489", "CWE-1188"],
      "plainLanguage": "A test-only switch that turns off security checks is still inside the app customers download.",
      "requirement": {
        "title": "Strip the certificate-bypass path from release builds",
        "given": "a production release build of the mobile app",
        "when": "the build is produced and inspected",
        "then": "the code path that accepts any certificate is excluded at compile time and no flag in the shipped artifact can re-enable it"
      }
    },
    {
      "stride": "Tampering",
      "title": "Bundled config file can be edited on the device to switch certificate checks off",
      "scenario": "The flag is read from a config file shipped with the app, so its value is attacker-reachable. On a rooted/jailbroken device, or after repackaging and resigning the app for distribution outside the official store, an attacker flips the flag in the config file. The app then trusts any certificate, letting the attacker intercept the victim's traffic and harvest credentials and session tokens.",
      "component": "Bundled config file read at runtime",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "The flag is read from a config file bundled in the release build." }
      ],
      "cwe": ["CWE-15", "CWE-345"],
      "plainLanguage": "Someone can edit the settings file inside the installed app to turn off the security check.",
      "requirement": {
        "title": "Do not take security decisions from a mutable on-device file",
        "given": "the app starts and reads its bundled configuration",
        "when": "the configuration file has been modified on the device to request relaxed certificate validation",
        "then": "the app ignores the value and enforces full certificate validation"
      }
    },
    {
      "stride": "Tampering",
      "title": "Intercepted responses can be rewritten to change what the app does and shows",
      "scenario": "Once certificate validation is bypassed, the man-in-the-middle not only reads traffic but also returns forged responses: fake balances or records, altered feature/permission payloads, or injected content and update URLs. The app has no other way to tell a genuine backend response from an attacker-supplied one, so the user acts on attacker-controlled data.",
      "component": "Mobile app to backend API channel",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "To help testing, the app accepts any TLS certificate when the environment flag is set." }
      ],
      "cwe": ["CWE-924"],
      "plainLanguage": "An attacker in the middle can also change the answers coming back, so the app displays and acts on fake data.",
      "requirement": {
        "title": "Ensure response integrity on the app-to-backend channel",
        "given": "the app receives a response from the backend",
        "when": "the response was produced by a network intermediary rather than the authenticated backend",
        "then": "the app rejects it because the TLS channel is authenticated against a validated certificate for the expected hostname"
      }
    }
  ]
}
